// Parse the AI output and return individual articles
const output = $input.item.json.output;
let articles = [];

try {
  if (typeof output === 'string') {
    const parsed = JSON.parse(output);
    articles = parsed.articles || parsed || [];
  } else if (output && output.articles) {
    articles = output.articles;
  } else if (Array.isArray(output)) {
    articles = output;
  }
} catch (e) {
  console.log('Parse error:', e.message);
  return [];
}

// Return each article as a separate item for looping
return articles.map(article => ({
  json: {
    title: article.title || '',
    url: article.url || '',
    date: article.date || '',
    categoryName: $('Workflow Configuration').item.json.categoryName
  }
}));

// Extract date and prepare article metadata
const articleUrl = $('Parse Articles to Items').item.json.url;
const turkishDate = $('Parse Articles to Items').item.json.date;
const originalTitle = $('Parse Articles to Items').item.json.title;
const categoryName = $('Parse Articles to Items').item.json.categoryName;

// Normalize Firecrawl output - try different possible field names
const input = $input.item.json;
let markdown = input.markdown || 
               input.data?.markdown || 
               input.content || 
               input.data?.content ||
               input.text ||
               '';

// If still empty, try to get the first string value
if (!markdown) {
  for (const key in input) {
    if (typeof input[key] === 'string' && input[key].length > 100) {
      markdown = input[key];
      break;
    }
  }
}

// Turkish month mapping
const turkishMonths = {
  'ocak': '01', 'şubat': '02', 'mart': '03', 'nisan': '04',
  'mayıs': '05', 'haziran': '06', 'temmuz': '07', 'ağustos': '08',
  'eylül': '09', 'ekim': '10', 'kasım': '11', 'aralık': '12'
};

// Parse Turkish date to ISO format (YYYY-MM-DD)
let isoDate = new Date().toISOString().split('T')[0];
try {
  const match = turkishDate.match(/(\d{1,2})\s+([a-zA-ZğüşıöçĞÜŞİÖÇ]+)\s+(\d{4})/i);
  if (match) {
    const day = match[1].padStart(2, '0');
    const monthName = match[2].toLowerCase();
    const year = match[3];
    const month = turkishMonths[monthName] || '01';
    isoDate = `${year}-${month}-${day}`;
  }
} catch (e) {
  console.log('Date parse error:', e.message);
}

return {
  json: {
    sourceUrl: articleUrl,
    turkishDate: turkishDate,
    isoDate: isoDate,
    originalTitle: originalTitle,
    categoryName: categoryName,
    markdown: markdown || ''
  }
};

